using System;using System.IO;using System.Linq;using System.Reflection;using System.Collections.Generic;using System.Windows;using System.Windows.Controls;using System.Windows.Media;using System.Windows.Media.Imaging;using System.Windows.Threading;using System.Web.Script.Serialization;using D=System.Drawing;
class PaletteCopyTests {
 static int checks,failures;static void Check(bool v,string n){checks++;Console.WriteLine((v?"PASS ":"FAIL ")+n);if(!v)failures++;}static object Get(object o,string n){return o.GetType().GetField(n,BindingFlags.Instance|BindingFlags.NonPublic|BindingFlags.Public).GetValue(o);}static object Call(object o,string n,params object[] a){return o.GetType().GetMethod(n,BindingFlags.Instance|BindingFlags.NonPublic|BindingFlags.Public).Invoke(o,a);}static IEnumerable<DependencyObject> Tree(DependencyObject o){yield return o;for(int i=0;i<VisualTreeHelper.GetChildrenCount(o);i++)foreach(var v in Tree(VisualTreeHelper.GetChild(o,i)))yield return v;}static T Named<T>(DependencyObject w,string n)where T:DependencyObject{Pump();return Tree(w).OfType<T>().First(c=>System.Windows.Automation.AutomationProperties.GetName(c)==n);}static void Pump(){var frame=new DispatcherFrame();var timer=new DispatcherTimer{Interval=TimeSpan.FromMilliseconds(100)};timer.Tick+=(s,e)=>{timer.Stop();frame.Continue=false;};timer.Start();Dispatcher.PushFrame(frame);}static void Click(Window w,string n){Tree(w).OfType<Button>().First(b=>Convert.ToString(b.Content)==n).RaiseEvent(new RoutedEventArgs(Button.ClickEvent));Pump();}static void Shot(Window w,string path){w.UpdateLayout();var root=(FrameworkElement)w.Content;var b=new RenderTargetBitmap((int)root.ActualWidth,(int)root.ActualHeight,96,96,PixelFormats.Pbgra32);b.Render(root);var e=new PngBitmapEncoder();e.Frames.Add(BitmapFrame.Create(b));using(var f=File.Create(path))e.Save(f);}
 static int Different(D.Bitmap a,D.Bitmap b){int count=0;for(int y=0;y<a.Height;y++)for(int x=0;x<a.Width;x++)if(a.GetPixel(x,y)!=b.GetPixel(x,y))count++;return count;}

 static bool Same(UsageRamp a,UsageRamp b){return new JavaScriptSerializer().Serialize(a)==new JavaScriptSerializer().Serialize(b);}
 static MonitorConfig Draft(Window w){return (MonitorConfig)Get(w,"taskbarDraft");}
 static void ExpandCopy(Window w){Named<Expander>(w,"指定项目配色复制").IsExpanded=true;Pump();}
 [STAThread]static int Main(string[] args){Directory.CreateDirectory(args[0]);Window pet=null;var app=new Application{ShutdownMode=ShutdownMode.OnExplicitShutdown};try{
 pet=(Window)Activator.CreateInstance(typeof(ConanPet),true);var assistant=(AssistantRuntime)Get(pet,"assistant");assistant.Config.Monitor.Quota.Enabled=false;((VoiceRuntime)Get(pet,"voices")).Settings.Enabled=false;var a=assistant.Config.Monitor.Appearance;a.EnsureItems();a.PerItemColors=false;foreach(var item in a.Items){item.LabelRamp=UsageRamp.Preset("基德月光");item.ValueRamp=UsageRamp.Preset("霞光琥珀");}a.Item("cpu").LabelRamp=UsageRamp.Preset("NVIDIA 绿");assistant.Save();pet.Show();Pump();((System.Threading.Timer)Get(pet,"assistantTimer")).Change(-1,-1);((DispatcherTimer)Get(pet,"ticker")).Stop();((DispatcherTimer)Get(pet,"skillTicker")).Stop();Call(pet,"OpenTerminal");var w=(TerminalWindow)Get(pet,"terminal");w.Width=1220;w.Height=980;w.ShowPage("任务栏外观");Named<Button>(w,"上移-cpu").RaiseEvent(new RoutedEventArgs(Button.ClickEvent));Click(w,"配色设计");Named<ComboBox>(w,"配色范围").SelectedItem=MonitorEngine.Label("cpu");Named<ComboBox>(w,"配色对象").SelectedIndex=2;Named<ComboBox>(w,"配色预设").SelectedItem="网络极光";Pump();var bar=Named<UsageRampBar>(w,"可编辑配色条");bar.SelectPoint(37);Named<TextBox>(w,"配色颜色点颜色").Text="#123ABC";Named<ComboBox>(w,"配色过渡方式").SelectedIndex=1;Named<Slider>(w,"配色色块数量").Value=23;var source=Draft(w).Appearance.Item("cpu").UsageRamp.Copy();Check(source.Stops.Any(p=>p.Position==37&&p.Color=="#123ABC"),"source selection remains CPU after row reordering");Check(!Same(source,Draft(w).Appearance.Item("upload").UsageRamp),"reordering cannot redirect source edits into another item");Click(w,"占用条");var graphSwitch=Named<CheckBox>(w,"显示资源占用条");graphSwitch.IsChecked=false;graphSwitch.RaiseEvent(new RoutedEventArgs(CheckBox.ClickEvent));Click(w,"配色设计");Named<Button>(w,"打开配色复制").RaiseEvent(new RoutedEventArgs(Button.ClickEvent));Pump();Check(Named<Expander>(w,"指定项目配色复制").IsExpanded,"visible shortcut opens destination picker");Check(!Named<CheckBox>(w,"配色复制目标-cpu").IsEnabled,"source excluded from destination selection");string before=new JavaScriptSerializer().Serialize(Draft(w));Click(w,"复制当前配色到勾选项目");Check(new JavaScriptSerializer().Serialize(Draft(w))==before&&Named<TextBlock>(w,"配色复制结果").Text.Contains("至少一个"),"empty destination selection is a no-op with inline guidance");var untouched=Draft(w).Appearance.Item("download").UsageRamp.Copy();var oldLabels=Draft(w).Appearance.Items.Select(i=>i.LabelRamp.Copy()).ToArray();Named<CheckBox>(w,"配色复制目标-gpu").IsChecked=true;Named<CheckBox>(w,"配色复制目标-memory").IsChecked=true;Click(w,"复制当前配色到勾选项目");Check(Same(Draft(w).Appearance.Item("gpu").UsageRamp,source)&&Same(Draft(w).Appearance.Item("memory").UsageRamp,source),"selected targets receive all color points positions and mosaic settings");Check(!Draft(w).Appearance.Graphs,"copy preserves global graph visibility switch");Check(Same(Draft(w).Appearance.Item("download").UsageRamp,untouched),"unselected bar palette unchanged");Check(Draft(w).Appearance.Items.Select((i,n)=>Same(i.LabelRamp,oldLabels[n])).All(x=>x),"bar copy never modifies text palettes");Check(!Object.ReferenceEquals(Draft(w).Appearance.Item("gpu").UsageRamp.Stops[0],Draft(w).Appearance.Item("memory").UsageRamp.Stops[0]),"target stop objects are independent deep copies");Check(Named<TextBlock>(w,"配色复制结果").Text.Contains(MonitorEngine.Label("gpu")),"feedback names actual selected destinations");Named<TextBox>(w,"配色颜色点颜色").Text="#FF1122";Check(Same(Draft(w).Appearance.Item("gpu").UsageRamp,source),"later source edits do not change copied targets");Shot(w,Path.Combine(args[0],"selective-palette-copy.png"));
 Named<ComboBox>(w,"配色对象").SelectedIndex=0;Pump();ExpandCopy(w);var labelSource=Draft(w).Appearance.Item("cpu").LabelRamp.Copy();var inherited=Draft(w).Appearance.TextRamp(Draft(w).Appearance.Item("download"),true).Copy();var valueBefore=Draft(w).Appearance.TextRamp(Draft(w).Appearance.Item("gpu"),false).Copy();Named<CheckBox>(w,"配色复制目标-gpu").IsChecked=true;Click(w,"复制当前配色到勾选项目");Check(Draft(w).Appearance.PerItemColors&&Same(Draft(w).Appearance.Item("gpu").LabelRamp,labelSource),"label copy enables selected independent text color");Check(Same(Draft(w).Appearance.TextRamp(Draft(w).Appearance.Item("download"),true),inherited),"enabling text overrides leaves unselected visible labels unchanged");Check(Same(Draft(w).Appearance.TextRamp(Draft(w).Appearance.Item("gpu"),false),valueBefore),"label copy preserves visible value text color");Check(Draft(w).Appearance.Item("download").LabelRamp.Stops.Count==4,"dormant independent palettes retain their stored colors");Named<ComboBox>(w,"配色对象").SelectedIndex=1;Pump();ExpandCopy(w);Click(w,"全选其他项目");Check(Tree(w).OfType<CheckBox>().Count(c=>System.Windows.Automation.AutomationProperties.GetName(c).StartsWith("配色复制目标-")&&c.IsChecked==true)==9,"select all excludes source");Click(w,"清空目标选择");Check(!Tree(w).OfType<CheckBox>().Any(c=>System.Windows.Automation.AutomationProperties.GetName(c).StartsWith("配色复制目标-")&&c.IsChecked==true),"clear selection clears all destinations");Named<CheckBox>(w,"配色复制目标-memory").IsChecked=true;var valueSource=Draft(w).Appearance.Item("cpu").ValueRamp.Copy();valueSource.Enabled=true;Click(w,"复制当前配色到勾选项目");Check(Same(Draft(w).Appearance.Item("memory").ValueRamp,valueSource),"value text color copied independently");Click(w,"应用并保存任务栏外观");var restored=new AssistantRuntime(AppDomain.CurrentDomain.BaseDirectory);Check(Same(restored.Config.Monitor.Appearance.Item("gpu").UsageRamp,source)&&Same(restored.Config.Monitor.Appearance.Item("gpu").LabelRamp,labelSource),"selected bar and label palettes survive runtime restart");Check(Same(restored.Config.Monitor.Appearance.Item("memory").ValueRamp,valueSource),"selected value palette survives runtime restart");restored.Telemetry.Dispose();var presets=TaskbarPresets.Save(assistant.Config.Monitor,"复制配色测试",Draft(w),false);assistant.Config.Monitor.TaskbarPresets=presets;var loaded=TaskbarPresets.Load(assistant.Config.Monitor,"复制配色测试");Check(Same(loaded.Appearance.Item("gpu").UsageRamp,source),"copied palette is reusable through existing appearance presets");Named<ComboBox>(w,"配色对象").SelectedIndex=3;Pump();Check(Named<Button>(w,"打开配色复制").Visibility==Visibility.Collapsed,"background hides project copy shortcut");Check(!Tree(w).OfType<Expander>().Any(e=>System.Windows.Automation.AutomationProperties.GetName(e)=="指定项目配色复制"),"single window background does not show invalid project destinations");w.SetTheme("b",false);Named<ComboBox>(w,"配色对象").SelectedIndex=2;ExpandCopy(w);Shot(w,Path.Combine(args[0],"selective-palette-copy-b.png"));
 }catch(Exception e){Console.WriteLine("FAIL "+e);failures++;}finally{if(pet!=null)pet.Close();app.Shutdown();}File.WriteAllText(Path.Combine(args[0],"palette-copy-results.json"),new JavaScriptSerializer().Serialize(new{checks,failures,isolated_settings=true}));return failures==0?0:1;}
